"""The 17 loot-box exclusive costumes, as voxel data. Original designs.
Box: [w,h,d,colour,x,y,z,flag]; flags: g glow, f flame, t see-through, s shiny, p rising particle, o orbiter.
b = on the body (body coords: torso y .42-.92, front z .15), h = on the head (head-local: head y 0-.56, face z .28), k = on the back."""
import math
def B(w,h,d,c,x,y,z,f=None):
    q=[round(w,3),round(h,3),round(d,3),c,round(x,3),round(y,3),round(z,3)]
    if f: q.append(f)
    return q
def mir(w,h,d,c,x,y,z,f=None): return [B(w,h,d,c,x,y,z,f),B(w,h,d,c,-x,y,z,f)]
def ring(n,r,y,w,h,d,c,f=None,ph=0,zc=0): return [B(w,h,d,c,math.sin(ph+i*2*math.pi/n)*r,y,zc+math.cos(ph+i*2*math.pi/n)*r,f) for i in range(n)]
def ringxy(n,r,cy,z,w,h,d,c,f=None,ph=0): return [B(w,h,d,c,math.sin(ph+i*2*math.pi/n)*r,cy+math.cos(ph+i*2*math.pi/n)*r,z,f) for i in range(n)]
def eyes(c,w=.14,h=.08,y=.3,f='g',x=.15): return mir(w,h,.02,c,x,y,.29,f)
C={}
def costume(id,name,myth,c,**k): C[id]=dict(name=name,myth=myth,c=c,**k)

